func TestLogBatchShutdownTimeout(t *testing.T) {
	exp := newLtExporter()
	exp.gate = make(chan struct{}) // never opened: export only ends on cancellation
	drops := &ltDrops{}
	p := ltNewProcessor(t, exp, BatchOptions{MaxBatchSize: 1, MaxQueueSize: 10, FlushInterval: time.Hour, OnDrop: drops.onDrop, MaxExportRetries: -1})
	for i := 0; i < 3; i++ {
		p.Add(context.Background(), ltRec("r"))
	}
	<-exp.entered
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	err := p.Shutdown(ctx)
	if !errors.Is(err, ErrTimeout) {
		t.Fatalf("shutdown = %v", err)
	}
	ltWait(t, "abort", func() bool { st := p.Stats(); return st.Queued == 0 && st.Failed+st.Dropped == 3 })
	if drops.count(DropReasonShutdown) == 0 {
		t.Fatalf("drops = %+v stats = %+v", drops, p.Stats())
	}
}

func TestLogBatchFlushContext(t *testing.T) {
	exp := newLtExporter()
	exp.gate = make(chan struct{})
	p := ltNewProcessor(t, exp, BatchOptions{FlushInterval: time.Hour})
	p.Add(context.Background(), ltRec("a"))
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := p.Flush(ctx); !errors.Is(err, ErrTimeout) { // worker accepted, export blocked
		t.Fatalf("flush = %v", err)
	}
	cctx, ccancel := context.WithCancel(context.Background())
	ccancel()
	if err := p.Flush(cctx); !errors.Is(err, ErrCancelled) { // worker busy, request not accepted
		t.Fatalf("flush = %v", err)
	}
	close(exp.gate)
}

