func TestLogBatchPartialAndPanics(t *testing.T) {
	drops := &ltDrops{}
	exp := newLtExporter()
	rejectErr := NewError(ErrorCodeValidation, "bad record", nil)
	exp.results = []ltResult{
		{res: ExportResult{Accepted: 1, Rejected: 2}},
		{res: ExportResult{Accepted: 0, Rejected: 3, Error: rejectErr}},
		{res: ExportResult{Accepted: 10}},
		{res: ExportResult{Accepted: -1, Rejected: 1}},
	}
	p := ltNewProcessor(t, exp, BatchOptions{MaxBatchSize: 3, MaxQueueSize: 3, FlushInterval: time.Hour, OnError: drops.onError})
	for round := 0; round < 4; round++ {
		for i := 0; i < 3; i++ {
			p.Add(context.Background(), ltRec("r"))
		}
		_ = p.Flush(context.Background())
	}
	st := p.Stats()
	if st.Sent != 1+0+3+0 || st.Failed != 2+3+0+3 {
		t.Fatalf("stats = %+v", st)
	}
	if len(drops.errs) != 3 || !errors.Is(drops.errs[0], ErrValidation) || drops.errs[1] != rejectErr {
		t.Fatalf("errors = %v", drops.errs)
	}

	panicky := newLtExporter()
	panicky.panicNext = true
	p2 := ltNewProcessor(t, panicky, BatchOptions{
		FlushInterval: time.Hour,
		OnDrop:        func([]LogRecord, DropReason) { panic("onDrop") },
		OnError:       func(error, []LogRecord) { panic("onError") },
	})
	p2.Add(context.Background(), ltRec("a"))
	_ = p2.Flush(context.Background())
	if st := p2.Stats(); st.Failed != 1 || st.Retries != 0 {
		t.Fatalf("panic stats = %+v", st)
	}
}
